-- Две мужские программы набора массы: «Масса · новичок» и «Масса · средний уровень».
--
-- 12 тренировок, три в неделю, сплит по дням:
--   день 1 — ноги, день 2 — жимовой (грудь/плечи/трицепс), день 3 — тяговый (спина/бицепс).
-- Слоты идут неделями: 1-3 первая неделя, 4-6 вторая и так далее.
--
-- По пять упражнений в тренировке, упор на базовые движения; пресс один раз
-- в неделю, во второй тренировке. Веса — стартовая точка, а не предписание:
-- движок прогрессии пересчитает их под человека после первых оценённых
-- подходов (см. computeTemplateScale в src/workoutPrompt.js). Подходы без веса
-- записаны как «× 20» — принятая запись собственного веса; «0 кг» писать
-- нельзя, ноль обнулит расчёт 1ПМ.

alter table program_templates add column if not exists icon        text;
alter table program_templates add column if not exists description text;
alter table program_templates add column if not exists subtitle    text;

-- 1. Базовые упражнения, которых не было в каталоге. Под каждое сделан ролик.
--    «Разгибание ног сидя в тренажёре» заведено про запас: в этих двух
--    программах не используется, ролик под него уже есть.
insert into catalog_exercises (name, muscle_group, equipment, type, hidden) values
  ('Жим штанги лёжа',                 'Грудь',  'Штанга',   'compound',  false),
  ('Жим штанги стоя',                 'Плечи',  'Штанга',   'compound',  false),
  ('Тяга штанги в наклоне',           'Спина',  'Штанга',   'compound',  false),
  ('Подъём штанги на бицепс',         'Руки',   'Штанга',   'isolation', false),
  ('Французский жим лёжа',            'Руки',   'Штанга',   'isolation', false),
  ('Жим ногами в тренажёре',          'Ноги',   'Тренажёр', 'compound',  false),
  ('Разгибание ног сидя в тренажёре', 'Ноги',   'Тренажёр', 'isolation', false),
  ('Подъём на носки стоя',            'Ноги',   'Тренажёр', 'isolation', false)
on conflict (name) do nothing;

